def workpath(p):
    p = str(p)
    return W / p[5:] if p.startswith("WORK/") else Path(p)

def read_roll(k):
    return [json.loads(s) for s in (W / f"roll_{k}.jsonl").read_text().splitlines() if s.strip()]

